// Get the busy array from Google Calendar
const calendarId = Object.keys($json.calendars)[0];
const busySlots = $json.calendars[calendarId].busy || [];

// Convert each slot into a readable text line
const formattedSlots = busySlots
  .map(slot => `• ${slot.start} → ${slot.end}`)
  .join("\n");

// Return clean text to feed the AI Agent
return [
  {
    json: {
      busySlots: formattedSlots,
      rawBusy: busySlots
    }
  }
];

// Parse Vapi tool call arguments - handles ALL payload formats
// Vapi sends data in multiple places simultaneously:
//   1. toolCallList[0].arguments (newer format)
//   2. toolCalls[0].function.arguments (older format)
//   3. toolWithToolCallList[0].toolCall.function.parameters (another format)

const body = $json.body.message;
let args = {};
let toolCallId = '';
let source = 'none';

// Helper: check if an object has any non-empty values
function hasData(obj) {
  if (!obj || typeof obj !== 'object') return false;
  return Object.values(obj).some(v => v !== '' && v !== null && v !== undefined);
}

// Try Source 1: toolCallList (newer Vapi format)
if (body.toolCallList && body.toolCallList.length > 0) {
  toolCallId = body.toolCallList[0].id || '';
  const a = body.toolCallList[0].arguments;
  if (typeof a === 'string') {
    try { const parsed = JSON.parse(a); if (hasData(parsed)) { args = parsed; source = 'toolCallList-string'; } } catch(e) {}
  } else if (hasData(a)) {
    args = a;
    source = 'toolCallList';
  }
}

// Try Source 2: toolCalls[0].function.arguments
if (!hasData(args) && body.toolCalls && body.toolCalls.length > 0) {
  if (!toolCallId) toolCallId = body.toolCalls[0].id || '';
  const a = body.toolCalls[0].function?.arguments;
  if (typeof a === 'string') {
    try { const parsed = JSON.parse(a); if (hasData(parsed)) { args = parsed; source = 'toolCalls-string'; } } catch(e) {}
  } else if (hasData(a)) {
    args = a;
    source = 'toolCalls';
  }
}

// Try Source 3: toolWithToolCallList
if (!hasData(args) && body.toolWithToolCallList && body.toolWithToolCallList.length > 0) {
  const tc = body.toolWithToolCallList[0].toolCall;
  if (tc) {
    if (!toolCallId) toolCallId = tc.id || '';
    const a = tc.function?.parameters || tc.function?.arguments;
    if (typeof a === 'string') {
      try { const parsed = JSON.parse(a); if (hasData(parsed)) { args = parsed; source = 'toolWithToolCallList-string'; } } catch(e) {}
    } else if (hasData(a)) {
      args = a;
      source = 'toolWithToolCallList';
    }
  }
}

// Fallback toolCallId from toolCallList if we got args from elsewhere
if (!toolCallId) {
  if (body.toolCallList?.[0]?.id) toolCallId = body.toolCallList[0].id;
  else if (body.toolCalls?.[0]?.id) toolCallId = body.toolCalls[0].id;
}

// Normalise the date field — handle multiple possible names
const dateValue = args.date_and_time || args.dateAndTime || args.datetime || args['date and time'] || args.date || '';

return [{
  json: {
    toolCallId,
    client_name: args.client_name || args.clientName || '',
    contact_name: args.contact_name || args.contactName || '',
    relationship: args.relationship || '',
    phone: args.phone || '',
    email: args.email || '',
    postcode: args.postcode || '',
    care_type: args.care_type || args.careType || '',
    date_and_time: dateValue,
    notes: args.notes || 'None provided',
    _debug_source: source,
    _debug_keys: Object.keys(args)
  }
}];

